namespace Kgp.Infrastructure.Photos;

/// <summary>Private storage for processed conquest photos. Names are generated by the API, never by the client.</summary>
public interface IPhotoStore
{
    Task SaveAsync(string name, byte[] content, CancellationToken ct);
    /// <summary>Opens the photo for reading, or returns null if it doesn't exist.</summary>
    Task<Stream?> OpenReadAsync(string name, CancellationToken ct);
    /// <summary>Deletes the photo; no error if it doesn't exist.</summary>
    Task DeleteAsync(string name, CancellationToken ct);
}

public sealed class StorageOptions
{
    /// <summary>Blob service endpoint (https://&lt;account&gt;.blob.core.windows.net/). Empty: use the local file system.</summary>
    public string? BlobEndpoint { get; set; }
    public string ContainerName { get; set; } = "conquest-photos";
    /// <summary>Folder for <see cref="FileSystemPhotoStore"/>. Defaults to kgp-photos in the temp folder.</summary>
    public string? LocalPath { get; set; }
}
